-- ===========================================================================
-- Team galleries online — migration 0054: how the service gets its keys.
--
--   1. The access secret is generated by the database, and nobody but the
--      service role can read it.
--   2. One publisher, registered by fingerprint during the connect window
--      only; a second computer is refused, and so is anyone after it closes.
--   3. Resetting who publishes is not something the Edge Function can do.
-- ===========================================================================
begin;
select plan(16);

select has_table('gallery', 'settings', 't_settings_table');
select ok((select relrowsecurity and relforcerowsecurity from pg_class
            where oid = 'gallery.settings'::regclass), 't_settings_rls_forced');
select ok(not has_table_privilege('anon', 'gallery.settings', 'select')
          and not has_table_privilege('authenticated', 'gallery.settings', 'select'),
  't_nobody_else_reads_the_secret');
select is((select count(*)::int from gallery.settings), 1, 't_one_settings_row');
select ok(length(decode((select access_secret from gallery.settings), 'base64')) = 32,
  't_access_secret_is_32_random_bytes');
select ok((select connect_until > now() + interval '23 hours' from gallery.settings),
  't_applying_opens_a_24_hour_connect_window');
select is((select publisher_key_sha256 from gallery.service_settings()), null,
  't_no_publisher_until_jerseysort_connects');

select throws_ok($$ select gallery.register_publisher('not-a-fingerprint') $$, '22023', null,
  't_a_fingerprint_is_64_hex');
select is(gallery.register_publisher(repeat('a', 64)), 'connected', 't_first_registration_connects');
select is((select connect_until from gallery.settings), null, 't_connecting_closes_the_window');
select is(gallery.register_publisher(repeat('a', 64)), 'connected', 't_the_same_computer_again_is_fine');
select is(gallery.register_publisher(repeat('b', 64)), 'taken', 't_another_computer_is_refused');
select is((select publisher_key_sha256 from gallery.service_settings()), repeat('a', 64),
  't_the_first_publisher_stays');

select ok(not has_function_privilege('service_role', 'gallery.reset_publisher(integer)', 'execute'),
  't_the_service_cannot_reset_the_publisher');
select gallery.reset_publisher(2);
select is(gallery.register_publisher(repeat('b', 64)), 'connected', 't_after_a_reset_a_new_computer_connects');
update gallery.settings set publisher_key_sha256 = null, connect_until = now() - interval '1 minute';
select is(gallery.register_publisher(repeat('c', 64)), 'closed', 't_after_the_window_nobody_connects');

select * from finish();
rollback;
